//! The kitchen-sink board: one board with a deliberate pass case and fail case for every check.
//!
//! It is `kitchen-sink` from the hardware repository, generated by its `generate.py` and `board.py`. Its README
//! says what each part is there for. These tests pin down every FAIL each command reports on it, so a change to
//! any checker that adds, drops or moves a finding shows up here, and they check that each section's pass case
//! really passes.

use std::path::{Path, PathBuf};
use std::sync::OnceLock;
use std::time::Duration;

use gerberus::bom::{self, Lcsc, Options, Topic};
use gerberus::design::Design;
use gerberus::inputs::BoardInputs;
use gerberus::kicad;
use gerberus::limits::Library;
use gerberus::pinout;
use gerberus::policy::Policy;
use gerberus::rules::{self, Finding, Report, Verdict};
use gerberus::si;
use gerberus::voltage::compute;

fn root(rel: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join(rel)
}

fn fixture(name: &str) -> PathBuf {
    root("tests/fixtures/kitchen-sink").join(name)
}

fn design() -> &'static Design {
    static DESIGN: OnceLock<Design> = OnceLock::new();
    DESIGN.get_or_init(|| kicad::load(&fixture("kitchen-sink.kicad_sch")).unwrap())
}

fn library() -> Library {
    Library::load_dir(&root("parts")).unwrap()
}

fn report() -> &'static Report {
    static REPORT: OnceLock<Report> = OnceLock::new();
    REPORT.get_or_init(|| {
        let lib = library();
        let policy = Policy::load(&root("policy.toml")).unwrap();
        let inputs = BoardInputs::load(&fixture("inputs.toml")).unwrap();
        let v = compute(design(), &lib, &inputs);
        rules::check(design(), &lib, &policy, &inputs, &v)
    })
}

/// `severity rule reference [case]` for every finding with this verdict, sorted, one line per finding.
fn listed(verdict: Verdict) -> Vec<String> {
    let mut out: Vec<String> = report()
        .findings
        .iter()
        .filter(|f| f.verdict == verdict)
        .map(|f| match &f.case {
            Some(case) => format!("{} {} {} [{case}]", f.severity, f.rule, f.reference),
            None => format!("{} {} {}", f.severity, f.rule, f.reference),
        })
        .collect();
    out.sort();
    out
}

fn find(rule: &str, reference: &str, case: Option<&str>) -> Vec<&'static Finding> {
    report()
        .findings
        .iter()
        .filter(|f| f.rule == rule && f.reference == reference && f.case.as_deref() == case)
        .collect()
}

/// Every finding of `rule` on `reference` (in `case`) has this verdict, and there is at least one.
fn all(rule: &str, reference: &str, case: Option<&str>, verdict: Verdict) {
    let f = find(rule, reference, case);
    assert!(!f.is_empty(), "no {rule} finding on {reference} ({case:?})");
    for f in f {
        assert_eq!(f.verdict, verdict, "{rule} {reference}: {}", f.message);
    }
}

#[test]
fn netlist_matches_the_board() {
    let d = design();
    assert!(d.warnings.is_empty(), "warnings: {:#?}", d.warnings);
    let pads = kicad::pcb::load_pad_nets(&fixture("kitchen-sink.kicad_pcb")).unwrap();
    let mut problems = Vec::new();
    let mut seen = std::collections::BTreeSet::new();
    for pad in pads {
        let Some(want) = pad.net else { continue };
        seen.insert((pad.reference.clone(), pad.pad.clone()));
        match d.pin_net(&pad.reference, &pad.pad) {
            Some(got) if got.name == want => {}
            got => problems.push(format!(
                "{}.{}: board {want:?}, schematic {:?}",
                pad.reference,
                pad.pad,
                got.map(|n| &n.name)
            )),
        }
    }
    for (r, c) in &d.components {
        for p in c.pins.keys() {
            if !seen.contains(&(r.clone(), p.clone())) {
                problems.push(format!("{r}.{p}: in the schematic but has no net on the board"));
            }
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
    // Bus members cross the hierarchy under their bus names.
    for (net, pins) in [
        ("/CANA.TXD", &["U4.1", "U6.1"][..]),
        ("/CANB.RXD", &["U5.4", "U6.15"]),
        ("/I2C.SDA", &["R7.2", "U6.31", "U8.10"]),
        ("/LED2", &["R17.1", "U7.8"]),
    ] {
        let n = d.net(net).unwrap_or_else(|| panic!("no net {net}"));
        let got: Vec<String> = n.pins.iter().map(|(r, p)| format!("{r}.{p}")).collect();
        assert_eq!(got, pins, "{net}");
    }
}

#[test]
fn check_fails_exactly_the_planted_bugs() {
    let want = [
        "error abs-max U3 [VAUX reversed]",
        "error abs-max U5 [VIN shorted onto CANH]",
        "error abs-max U5 [VIN shorted onto CANL]",
        "error abs-max U6",
        "error cap-voltage C2",
        "error floating-input U3",
        "error forward-current D17",
        "error junction-temperature U7",
        "error recommended R15",
        "error recommended R16",
        "error recommended R17",
        "error recommended R3",
        "error resistor-power R15",
        "error resistor-power R16",
        "error resistor-power R17",
        "error resistor-power R3",
        "error reverse-polarity J2 [VAUX reversed]",
        "error tvs-breakdown D3",
        "error unpowered U9",
        "warning esd J3",
        "warning esd J3",
        "warning esd J3",
        "warning forward-current D15",
        "warning forward-current D16",
        "warning recommended U6",
        "warning regulator-headroom U3",
        "warning tvs-standoff D11",
        "warning tvs-standoff D3",
    ];
    assert_eq!(listed(Verdict::Fail), want);
    // The esd warnings are J3's three pins: VTref (+3V3), SWDIO and SWCLK.
    let esd: Vec<&str> = find("esd", "J3", None)
        .iter()
        .map(|f| f.message.split(' ').next().unwrap())
        .collect();
    assert_eq!(esd, ["J3.1", "J3.2", "J3.3"]);
}

#[test]
fn check_messages_cite_the_numbers() {
    let cases: [(&str, &str, Option<&str>, &[&str]); 10] = [
        ("abs-max", "U6", None, &["PA4", "/mcu/VSENSE", "26 V", "4 V"]),
        (
            "abs-max",
            "U5",
            Some("VIN shorted onto CANH"),
            &["CANH", "26 V", "14 V"],
        ),
        ("tvs-breakdown", "D3", None, &["+VDC", "26 V", "20 V"]),
        ("cap-voltage", "C2", None, &["26 V", "25 V"]),
        ("floating-input", "U3", None, &["CE"]),
        ("unpowered", "U9", None, &["VDD", "/sensors/+3V3_ENC"]),
        ("regulator-headroom", "U3", None, &["/power/VAUX", "can fall to 3 V"]),
        ("recommended", "U6", None, &["PA4", "26 V"]),
        ("junction-temperature", "U7", None, &["371.4 mW", "70 °C", "105"]),
        ("forward-current", "D17", None, &["28.46 mA", "25 mA"]),
    ];
    for (rule, reference, case, needles) in cases {
        let fails: Vec<_> = find(rule, reference, case)
            .into_iter()
            .filter(|f| f.verdict == Verdict::Fail)
            .collect();
        assert!(!fails.is_empty(), "no {rule} FAIL on {reference}");
        for f in fails {
            for n in needles {
                assert!(
                    f.message.contains(n),
                    "{rule} {reference}: missing {n:?} in {}",
                    f.message
                );
            }
        }
    }
}

#[test]
fn each_section_has_a_pass_case() {
    // power: the protected input, the good TVS and capacitor, the regulators with headroom.
    assert!(
        listed(Verdict::Fail).iter().all(|f| !f.contains("VIN reversed")),
        "VIN is blocked by D1"
    );
    all("tvs-breakdown", "D2", None, Verdict::Pass);
    all("tvs-standoff", "D2", None, Verdict::Pass);
    all("cap-voltage", "C1", None, Verdict::Pass);
    all("regulator-headroom", "U1", None, Verdict::Pass);
    all("regulator-headroom", "U2", None, Verdict::Pass);
    // can: the fault-protected transceiver survives VIN on either wire, and its strap pin is driven.
    all("abs-max", "U4", Some("VIN shorted onto CANH"), Verdict::Pass);
    all("abs-max", "U4", Some("VIN shorted onto CANL"), Verdict::Pass);
    all("floating-input", "U4", None, Verdict::Pass);
    // mcu: clamped UART pins, and USB pins clamped (port 1) or covered by a surge diode (port 2).
    for reference in ["J4", "J5", "J6"] {
        all("esd", reference, None, Verdict::Pass);
    }
    // thermal: the LED through 1k, and the MCUs and transceivers that aren't overloaded.
    all("forward-current", "D8", None, Verdict::Pass);
    for reference in ["U4", "U5", "U6"] {
        all("junction-temperature", reference, None, Verdict::Pass);
    }
    // sensors: the powered sensor.
    all("unpowered", "U8", None, Verdict::Pass);
}

#[test]
fn pinout_finds_the_swapped_led() {
    let fps = kicad::pcb::load_footprints(&fixture("kitchen-sink.kicad_pcb")).unwrap();
    let r = pinout::check(design(), Some(&fps), &library());
    let refs = |s: pinout::Severity| {
        let mut v: Vec<&str> = r
            .findings
            .iter()
            .filter(|f| f.severity == s)
            .map(|f| f.reference.as_str())
            .collect();
        v.sort_unstable();
        v.dedup();
        v
    };
    assert_eq!(refs(pinout::Severity::Error), ["D5"]);
    assert!(
        r.findings
            .iter()
            .any(|f| f.reference == "D5" && f.message.contains("pins look swapped"))
    );
    // The known differences between KiCad's symbols and the datasheets, as on the other boards.
    assert_eq!(
        refs(pinout::Severity::Warning),
        ["D2", "D3", "D4", "J5", "J6", "U4", "U8"]
    );
}

#[test]
fn si_passes_port_1_and_fails_port_2() {
    let layout = kicad::pcb::load_layout(&fixture("kitchen-sink.kicad_pcb")).unwrap();
    let r = si::check(&layout, &library());
    let fails = |pair: &str| {
        let mut v: Vec<&str> = r
            .findings
            .iter()
            .filter(|f| f.pair == pair && f.verdict == Verdict::Fail)
            .map(|f| f.rule)
            .collect();
        v.sort_unstable();
        v
    };
    assert_eq!(fails("USB1"), Vec::<&str>::new());
    assert_eq!(
        fails("USB2"),
        [
            "usb-capacitance",
            "usb-capacitance",
            "usb-eye",
            "usb-impedance",
            "usb-reference",
            "usb-reference",
            "usb-skew",
            "usb-stubs",
            "usb-stubs",
            "usb-stubs",
            "usb-vias",
        ]
    );
}

#[test]
fn bom_finds_the_wrong_lcsc_number_and_empty_stock() {
    let mut lcsc = Lcsc::new(Some(root("tests/fixtures/lcsc")), Duration::ZERO, true);
    let report = bom::check(design(), &mut lcsc, Options::default());
    let mut errors: Vec<(String, Topic)> = report
        .iter()
        .flat_map(|h| {
            h.findings
                .iter()
                .filter(|f| f.severity == bom::Severity::Error)
                .map(|f| (h.line.references[0].clone(), f.topic))
        })
        .collect();
    errors.sort_by(|a, b| a.0.cmp(&b.0));
    assert_eq!(
        errors,
        [
            // C4 and R4-R6 are JLCPCB basic parts LCSC's retail stock had run out of on 2026-11-17.
            ("C4".to_string(), Topic::Stock),
            ("C7".to_string(), Topic::Identity),
            ("D11".to_string(), Topic::Stock),
            ("R4".to_string(), Topic::Stock),
            ("R5".to_string(), Topic::Stock),
            ("R6".to_string(), Topic::Stock),
            ("U4".to_string(), Topic::Stock),
        ]
    );
    let line = |r: &str| {
        report
            .iter()
            .find(|h| h.line.references.iter().any(|x| x == r))
            .unwrap()
    };
    assert!(
        line("U8")
            .findings
            .iter()
            .any(|f| f.severity == bom::Severity::Warning && f.message.contains("no listing"))
    );
    assert!(
        line("TP1")
            .findings
            .iter()
            .any(|f| f.severity == bom::Severity::Unknown)
    );
    assert!(line("J5").findings.iter().all(|f| f.severity == bom::Severity::Info));
}

/// The terminal report reads like rustc's: a headline per FAIL with where it is, its numbers and sources as
/// notes and a suggested fix, errors before warnings, UNKNOWNs and passes counted but not listed, and the long
/// explanations of each net only with --verbose. The JSON keeps every field as it was.
#[test]
fn the_report_reads_like_rustc() {
    use gerberus::diag::Show;
    let lib = library();
    let inputs = BoardInputs::load(&fixture("inputs.toml")).unwrap();
    let v = compute(design(), &lib, &inputs);
    let r = report();
    let text = rules::render(design(), &v, r, &Show::default());
    assert!(text.starts_with(
        "error[abs-max]: U6.PA4 reaches 26 V, past the maximum of 4 V\n  --> U6.PA4 (/mcu/VSENSE)\n   = note: worst \
         case 0 to 26 V\n   = note: STM32G0B1KBT6TR DS13560 Rev 3 p66, any pin other than FT_xx\n   = help: "
    ));
    for want in [
        "error[abs-max]: U5.CANH reaches 26 V, past the maximum of 14 V\n  --> U5.CANH (/CANH), in fault \"VIN \
         shorted onto CANH\"",
        "error[cap-voltage]: C2.1: 26 V across it, past its 25 V rating\n",
        "error[junction-temperature]: U7 dissipates 371.4 mW, so its junction reaches 114 °C at 70 °C ambient, \
         above its 105 °C maximum\n",
        "warning[regulator-headroom]: U3 may not hold /power/+3V3A: /power/VAUX can fall to 3 V",
        "and 9 more like these (--verbose lists them)",
        "error: 18 errors, 9 warnings, 109 unknown, 402 passed\n   = note: 109 unknown and 402 passed not shown; \
         --unknown or --all lists them\n",
    ] {
        assert!(text.contains(want), "missing {want:?} in\n{text}");
    }
    // Every error comes before the first warning, and nothing else is listed.
    let last_error = text.rfind("\nerror[").unwrap();
    assert!(last_error < text.find("\nwarning[").unwrap());
    assert!(!text.contains("unknown[") && !text.contains("pass["));
    // The 18 errors and the reverse-polarity summary, which the totals leave out.
    assert_eq!(text.matches("error[").count(), 19);
    // How +VDC gets to 26 V, and the GND reference list, only with --verbose.
    assert!(!text.contains("the reference of input"));
    let verbose = rules::render(
        design(),
        &v,
        r,
        &Show {
            verbose: true,
            ..Show::default()
        },
    );
    assert!(verbose.contains("   = note: how /mcu/VSENSE gets 0 to 26 V:\n       /mcu/VSENSE: 0 to 26 V\n"));
    assert!(verbose.contains("the reference of input VIN (J1.4)"));
    let all = rules::render(design(), &v, r, &Show::everything());
    assert_eq!(all.matches("\nunknown[").count(), 109);
    // Passes include the reverse-polarity summaries, which the totals leave out.
    let passes = r.findings.iter().filter(|f| f.verdict == Verdict::Pass).count();
    assert_eq!((passes, all.matches("\npass[").count()), (403, 403));
    // No colour unless asked for.
    assert!(!text.contains('\x1b'));

    let json: serde_json::Value = serde_json::to_value(r).unwrap();
    let keys: std::collections::BTreeSet<&str> = json["findings"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|f| f.as_object().unwrap().keys().map(String::as_str))
        .collect();
    assert_eq!(
        keys.into_iter().collect::<Vec<_>>(),
        ["case", "message", "reference", "rule", "severity", "verdict"]
    );
}
